import re
import json
from collections import Counter

_URL_PATTERN = re.compile(r"https?://[^\s<>'\"`]+", re.IGNORECASE)
_TRAILING_PUNCTUATION = ".,;:!?)]}"


def _extract_urls_from_string(text):
    urls = []
    for match in _URL_PATTERN.findall(text):
        url = match.rstrip(_TRAILING_PUNCTUATION)
        if url:
            urls.append(url)
    return urls


def _walk_json(obj):
    if isinstance(obj, str):
        return _extract_urls_from_string(obj)

    urls = []

    if isinstance(obj, dict):
        for value in obj.values():
            urls.extend(_walk_json(value))
    elif isinstance(obj, list):
        for item in obj:
            urls.extend(_walk_json(item))
    elif isinstance(obj, tuple):
        for item in obj:
            urls.extend(_walk_json(item))

    return urls


def task_func(json_str, top_n=10):
    if not isinstance(json_str, str):
        json_str = str(json_str)

    try:
        data = json.loads(json_str)
    except (TypeError, ValueError, json.JSONDecodeError):
        data = json_str

    urls = _walk_json(data)
    if not urls and isinstance(data, str):
        urls = _extract_urls_from_string(data)

    counts = Counter(urls)

    try:
        top_n = int(top_n)
    except (TypeError, ValueError):
        top_n = 10

    if top_n <= 0:
        return {}

    return dict(counts.most_common(top_n))
