import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    """
    Extract URLs from a string-serialized JSON dict and count occurrences.

    Args:
        json_str: String-serialized JSON object.
        top_n: Kept for compatibility; if provided and positive, returns only
               the top_n most common URLs. If None or <= 0, returns all.

    Returns:
        dict: A dict with URLs as keys and the number of times they appear as values.
    """
    url_pattern = re.compile(r'https?://[^\s\'"<>\]\[{}()]+', re.IGNORECASE)

    def clean_url(url):
        return url.rstrip('.,;:!?)]}\'"')

    def walk(obj):
        if isinstance(obj, str):
            for match in url_pattern.findall(obj):
                cleaned = clean_url(match)
                if cleaned:
                    yield cleaned
        elif isinstance(obj, dict):
            for value in obj.values():
                yield from walk(value)
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                yield from walk(item)

    try:
        data = json.loads(json_str)
    except Exception:
        data = json_str

    counts = Counter(walk(data))

    if top_n is not None and top_n > 0:
        return dict(counts.most_common(top_n))
    return dict(counts)
