import urllib.request
from pyquery import PyQuery as pq
from datetime import datetime
import pandas as pd
from urllib.error import URLError
from urllib.parse import urlparse

def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("Invalid or empty URL")

    clean_url = url.strip()
    parsed = urlparse(clean_url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError("Invalid or empty URL")

    try:
        with urllib.request.urlopen(clean_url) as response:
            content_type = response.headers.get_content_charset()
            html = response.read().decode(content_type or "utf-8", errors="replace")
    except URLError:
        raise
    except ValueError as exc:
        raise ValueError("Invalid or empty URL") from exc

    fetch_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    doc = pq(html)

    records = []
    for anchor in doc("a").items():
        records.append(
            {
                "text": (anchor.text() or "").strip(),
                "href": anchor.attr("href"),
                "fetch_time": fetch_time,
            }
        )

    return pd.DataFrame(records, columns=["text", "href", "fetch_time"])
