import json
import math

def task_func(decimal_value, precision=2):
    """
    Calculate the square root of decimal_value to the requested precision
    and return it encoded as a JSON string.
    """
    try:
        value = float(decimal_value)
    except (TypeError, ValueError) as exc:
        raise ValueError("decimal_value must be a real number") from exc

    try:
        precision = int(precision)
    except (TypeError, ValueError) as exc:
        raise ValueError("precision must be an integer") from exc

    if precision < 0:
        precision = 0
    if value < 0:
        raise ValueError("decimal_value must be non-negative")

    root = math.sqrt(value)
    formatted = f"{root:.{precision}f}"
    return json.dumps(formatted)
