import mechanize
from bs4 import BeautifulSoup


def task_func(url, form_id, data):
    br = mechanize.Browser()
    br.set_handle_robots(False)
    br.set_handle_refresh(False)

    initial_response = br.open(url)

    forms = list(br.forms())
    chosen_index = None

    for i, form in enumerate(forms):
        attrs = getattr(form, "attrs", {}) or {}
        if str(attrs.get("id")) == str(form_id) or str(attrs.get("name")) == str(form_id):
            chosen_index = i
            break

    if chosen_index is None:
        try:
            idx = int(form_id)
            chosen_index = idx if 0 <= idx < len(forms) else 0
        except Exception:
            chosen_index = 0 if forms else None

    if chosen_index is None:
        return "No Title"

    br.select_form(nr=chosen_index)

    for key, value in (data or {}).items():
        try:
            br.form[key] = value
        except Exception:
            try:
                if isinstance(value, (list, tuple, set)):
                    br.form[key] = list(value)
                else:
                    br.form[key] = "" if value is None else str(value)
            except Exception:
                pass

    try:
        response = br.submit()
    except Exception:
        response = initial_response

    html = response.read()
    if isinstance(html, bytes):
        html = html.decode("utf-8", "ignore")

    soup = BeautifulSoup(html, "html.parser")
    if soup.title and soup.title.string and soup.title.string.strip():
        return soup.title.string.strip()
    return "No Title"
